import java.util.*;
import java.io.*;

public class q4 {
    public static void main(String[] args) throws IOException {
        BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
        String[] firstLine = reader.readLine().split(" ");
        int n = Integer.parseInt(firstLine[0]);
        int b = Integer.parseInt(firstLine[1]);
        int[] array = new int[n + 1];
        int[] oddCountPrefix = new int[n + 1];
        int[] evenCountPrefix = new int[n + 1];

        String[] inputLine = reader.readLine().split(" ");
        for (int i = 1; i <= n; i++) {
            array[i] = Integer.parseInt(inputLine[i - 1]);
            if (array[i] % 2 == 1) {
                oddCountPrefix[i] = oddCountPrefix[i - 1] + 1;
                evenCountPrefix[i] = evenCountPrefix[i - 1];
            } else {
                oddCountPrefix[i] = oddCountPrefix[i - 1];
                evenCountPrefix[i] = evenCountPrefix[i - 1] + 1;
            }
        }

        int cuts = 0;
        int[] diffArray = new int[n / 2 - 1];
        for (int i = 2; i < n; i += 2) {
            if (oddCountPrefix[i] == evenCountPrefix[i]) {
                diffArray[i / 2 - 1] = Math.abs(array[i] - array[i + 1]);
            } else {
                diffArray[i / 2 - 1] = -1;
            }
        }
        Arrays.sort(diffArray);
        long total = 0;
        for (int val : diffArray) {
            if (val != -1 && total + val <= b) {
                cuts++;
                total += val;
            }
        }
        System.out.println(cuts);
    }
}
